var i=`amdahl-s-law`;var o=106;var a={en:[{id:`T106-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Amdahl's Law`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Cost–benefit analysis estimates whether expected business value justifies implementation, maintenance and risk.`},{id:`B`,text:`The Theory of Constraints holds that overall throughput is limited by a small number of bottlenecks.`},{id:`C`,text:`An ADR records an architectural choice, the context that motivated it, alternatives, consequences and status.`},{id:`D`,text:`Amdahl's Law bounds the speedup of a workload when only part can be parallelized.`}]},{id:`T106-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Amdahl's Law`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Measure arrivals, completed throughput, waiting and processing time over compatible boundaries and steady periods.`},{id:`B`,text:`Estimate upfront effort, ongoing operations, avoided incidents, delivery acceleration and opportunity cost.`},{id:`C`,text:`Identify the current constraint, exploit it efficiently, subordinate upstream work to its capacity, elevate capacity when justified and repeat as bottlenecks move.`},{id:`D`,text:`Measure how much work remains serial, then include actual parallel overhead, communication and contention.`}]},{id:`T106-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`If 20% of a report is serial, the theoretical maximum speedup is 5 times regardless of added workers.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Factor in support, edge cases and reliability of the automation.`},{id:`B`,text:`Independent test automation may be more parallelizable.`},{id:`C`,text:`Database contention may lower it further.`},{id:`D`,text:`Increasing upload workers only grows the queue; parallelizing or optimizing OCR may improve completion throughput.`}]},{id:`T106-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Amdahl's Law`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Benefits such as developer happiness or lower risk are real but hard to monetize; document them explicitly.`},{id:`B`,text:`Little's Law does not predict tail latency or fix overload.`},{id:`C`,text:`Amdahl assumes a fixed workload and idealized parallel execution; real workloads can grow and require Gustafson-style scaling analysis.`},{id:`D`,text:`Bottlenecks shift under different workloads.`}]},{id:`T106-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`With serial fraction s and p processors, idealized speedup is 1 divided by (s plus (1 minus s) divided by p).`}]}]},{id:`T106-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Doubling the number of CPU cores always halves total application execution time.`}]}]},{id:`T106-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Do not confuse latency speedup with throughput increase.`}]}]},{id:`T106-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Amdahl's Law`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Parallelizing the nonparallel portion can remove the serial execution limit.`},{id:`B`,text:`Measure how much work remains serial, then include actual parallel overhead, communication and contention.`},{id:`C`,text:`An option with the lowest initial price always has the lowest total cost.`},{id:`D`,text:`Amdahl's Law bounds the speedup of a workload when only part can be parallelized.`}]},{id:`T106-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Amdahl's Law`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Do not confuse latency speedup with throughput increase.`},{id:`B`,text:`Expected maintenance and exit costs should be excluded from economic analysis.`},{id:`C`,text:`Database contention may lower it further.`},{id:`D`,text:`Doubling the number of CPU cores always halves total application execution time.`}]},{id:`T106-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`If 20% of a report is serial, the theoretical maximum speedup is 5 times regardless of added workers.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to estimate three automation options using low, base and high scenarios, including operating costs and a break-even point.`},{id:`B`,text:`Ask an agent to map throughput across an import pipeline, identify the bottleneck from measurements and propose staged improvements with before/after flow metrics.`},{id:`C`,text:`Ask an agent to benchmark sequential and parallel report generation, estimate serial fraction, compare observed speedup with Amdahl's bound and explain overhead.`},{id:`D`,text:`Ask an agent to calculate and validate queue metrics from production-like traces, detect unstable load and propose a capacity threshold with alerts.`}]},{id:`T106-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Why can doubling workers yield almost no speedup despite ample CPU capacity?`}]}]},{id:`T106-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`If 20% of a report is serial, the theoretical maximum speedup is 5 times regardless of added workers.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Amdahl's Law`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T106-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`If 20% of a report is serial, the theoretical maximum speedup is 5 times regardless of added workers.`,b:!0},{t:` — propose three checks for `},{t:`Amdahl's Law`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T106-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`If 20% of a report is serial, the theoretical maximum speedup is 5 times regardless of added workers.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T106-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Amdahl's Law`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`If 20% of a report is serial, the theoretical maximum speedup is 5 times regardless of added workers.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T106-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Закон Амдала`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Аналіз витрат і вигод оцінює, чи виправдовує очікувана користь реалізацію, підтримку й ризик.`},{id:`B`,text:`Теорія обмежень стверджує, що загальну пропускну здатність обмежує невелика кількість вузьких місць.`},{id:`C`,text:`ADR фіксує архітектурний вибір, його контекст, альтернативи, наслідки та стан.`},{id:`D`,text:`Закон Амдала обмежує прискорення програми, коли лише частину можна розпаралелити.`}]},{id:`T106-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Закон Амдала`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Вимірюйте надходження, завершену пропускну здатність, очікування й обробку в однакових межах і стабільному періоді.`},{id:`B`,text:`Оцініть стартову працю, експлуатаційні витрати, уникнені інциденти, прискорення релізів і альтернативну вартість.`},{id:`C`,text:`Визначте обмеження, використайте його ефективно, узгодьте роботу інших ділянок із його потужністю, збільште потужність за потреби та повторіть цикл.`},{id:`D`,text:`Вимірюйте послідовну частку та накладні витрати на координацію, комунікацію й конкуренцію.`}]},{id:`T106-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Якщо 20% генерації звіту послідовні, теоретична межа прискорення — 5 разів за будь-якої кількості воркерів.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Врахуйте підтримку, винятки й надійність процесу.`},{id:`B`,text:`Незалежна автоматизація тестів може бути кращою паралельною задачею.`},{id:`C`,text:`Конкуренція за БД зменшить результат.`},{id:`D`,text:`Додавання upload-воркерів лише збільшує чергу; оптимізація OCR може підвищити загальну пропускну здатність.`}]},{id:`T106-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Закон Амдала`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Переваги на кшталт задоволення команди чи зниження ризику реальні, хоча їх важко оцінити грошима; фіксуйте їх.`},{id:`B`,text:`Закон Літтла не передбачає хвостові затримки й не усуває перевантаження.`},{id:`C`,text:`Амдал припускає фіксоване завдання й ідеальну паралельність; реальне навантаження може зростати, де корисний аналіз Густафсона.`},{id:`D`,text:`Вузькі місця змінюються за різного навантаження.`}]},{id:`T106-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`За послідовної частки s та p процесорів ідеалізоване прискорення дорівнює 1 поділити на (s плюс (1 мінус s), поділене на p).`}]}]},{id:`T106-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Подвоєння ядер CPU завжди вдвічі скорочує загальний час виконання.`}]}]},{id:`T106-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Не плутайте прискорення окремого запиту з пропускною здатністю.`}]}]},{id:`T106-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Закон Амдала`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Розпаралелювання непаралельної частини усуває обмеження послідовного виконання.`},{id:`B`,text:`Вимірюйте послідовну частку та накладні витрати на координацію, комунікацію й конкуренцію.`},{id:`C`,text:`Варіант із найнижчою стартовою ціною завжди має найнижчу загальну вартість.`},{id:`D`,text:`Закон Амдала обмежує прискорення програми, коли лише частину можна розпаралелити.`}]},{id:`T106-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Закон Амдала`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Не плутайте прискорення окремого запиту з пропускною здатністю.`},{id:`B`,text:`Очікувану підтримку та вартість виходу потрібно виключати з економічного аналізу.`},{id:`C`,text:`Конкуренція за БД зменшить результат.`},{id:`D`,text:`Подвоєння ядер CPU завжди вдвічі скорочує загальний час виконання.`}]},{id:`T106-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Якщо 20% генерації звіту послідовні, теоретична межа прискорення — 5 разів за будь-якої кількості воркерів.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента оцінити три способи автоматизації за песимістичним, базовим та оптимістичним сценаріями з експлуатаційними витратами й точкою окупності.`},{id:`B`,text:`Попросіть агента зіставити пропускну здатність етапів імпорту, знайти вузьке місце за вимірами й запропонувати поетапні покращення з порівнянням результату.`},{id:`C`,text:`Попросіть агента заміряти послідовне й паралельне формування звіту, оцінити послідовну частку, зіставити результат із законом Амдала та пояснити накладні витрати.`},{id:`D`,text:`Попросіть агента розрахувати й перевірити метрики черги з реалістичних traces, виявити нестабільне навантаження та запропонувати поріг потужності й alerts.`}]},{id:`T106-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Чому подвоєння воркерів може майже не пришвидшити роботу за достатньої CPU-потужності?`}]}]},{id:`T106-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Якщо 20% генерації звіту послідовні, теоретична межа прискорення — 5 разів за будь-якої кількості воркерів.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Закон Амдала`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T106-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Якщо 20% генерації звіту послідовні, теоретична межа прискорення — 5 разів за будь-якої кількості воркерів.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Закон Амдала`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T106-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Якщо 20% генерації звіту послідовні, теоретична межа прискорення — 5 разів за будь-якої кількості воркерів.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T106-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Закон Амдала`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Якщо 20% генерації звіту послідовні, теоретична межа прискорення — 5 разів за будь-якої кількості воркерів.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var s={slug:i,topicId:106,questions:a};export{s as default,a as questions,i as slug,o as topicId};